// the row types of an ORM, computed from table definitions, like those of drizzle-orm and kysely

export interface Column<T, TNullable extends boolean = false> {
  readonly _: { data: T; nullable: TNullable }
}

type Simplify<T> = { [K in keyof T]: T[K] } & {}

export type InferSelectModel<TTable extends Table<any>> = Simplify<{
  [K in keyof TTable['columns']]: TTable['columns'][K] extends Column<infer D, infer N>
    ? N extends true
      ? D | null
      : D
    : never
}>

export interface Table<TColumns extends Record<string, Column<any, boolean>>> {
  readonly columns: TColumns
  readonly $inferSelect: InferSelectModel<Table<TColumns>>
}

export type Selectable<T> = {
  [K in keyof T]: T[K] extends Column<infer D, boolean> ? D : T[K]
}

// the records of a generated client, like those of Prisma, whose fields it declares itself
export interface Records {
  post: { id: number; title: string; authorId: number }
}

// the documents of an ODM with timestamps, like those of mongoose
export interface Schema<TFields> {
  readonly fields: TFields
}

export type InferDocument<TSchema> =
  TSchema extends Schema<infer F> ? Simplify<F> & { createdAt: Date; updatedAt: Date } : never

// a value of a library with a name of its own
export interface DecimalLike {
  digits: number[]
  exponent: number
}
